// #aaeb71 (6a60d51d) — TC-PUSH-01…04: push about a new chat message arrives on Android (Alina 146) in 4 receiver states.
// One process = one platform (lib/session.js), so the sender (iPhone, נקיה 140 = PARTNER) is NOT driven here:
//   QA_PUSH_SENDER=manual → for each state the test prints the exact text to send from the iPhone and waits for it in
//   `adb shell dumpsys notification --noredact` (pkg com.yb.findworkers, android.title / android.text).
//   Without QA_PUSH_SENDER the receive checks are skipped; only the permission precondition runs.
// Messages "QA-AUTO push …" stay in the Alina↔נקיה test chat (no delete in chat) — list them for cleanup.
// TC-PUSH-05…10 (iPhone receiver, fresh install + Allow) are manual only.
import assert from 'node:assert/strict';
import { startDriver, goTab, byText, PARTNER, APP_ID, IS_IOS } from '../lib/session.js';
import { waitForNotification, notificationPermissionGranted, killInBackground, processRunning } from '../lib/android-notifications.js';

const SENDER = process.env.QA_PUSH_SENDER; // 'manual' — a person sends from the iPhone (PARTNER)
const WAIT = Number(process.env.QA_PUSH_WAIT_MS || 180000); // time for a person to type + delivery (seen 2–3 s)
const partnerFirst = PARTNER.name.split(' ')[0];
const stamp = () => new Date().toTimeString().slice(0, 8).replace(/:/g, '');

describe('Push on new chat message, receiver Android #aaeb71 @android @data', function () {
  this.timeout(WAIT + 120000);
  let d; const sent = [];
  before(async function () { if (IS_IOS) this.skip(); d = await startDriver(); });
  after(async () => {
    if (sent.length) console.log(`[cleanup] messages left in chat ${partnerFirst}→Alina: ${sent.join(' | ')}`);
    if (d) { try { if (await d.isLocked()) await d.unlock(); } catch {} await d.deleteSession(); }
  });

  /** Ask the person at the iPhone to send `text` to this account, then wait for the Android notification. */
  async function expectPushFromPartner(state) {
    const text = `QA-AUTO push ${state} ${stamp()}`;
    sent.push(text);
    console.log(`\n>>> iPhone (${PARTNER.name}): send to Alina in chat exactly: "${text}" (waiting ${WAIT / 1000}s)\n`);
    const n = await waitForNotification(APP_ID, text, { timeout: WAIT });
    assert.ok(n.title && n.title.includes(partnerFirst), `push title must name the sender "${partnerFirst}", got "${n.title}"`);
    assert.ok(n.text.includes(text), 'push text = message text');
    return n;
  }

  it('precondition: POST_NOTIFICATIONS granted to the app (Allow was pressed) @prod-safe', async () => {
    assert.ok(notificationPermissionGranted(APP_ID), `${APP_ID}: POST_NOTIFICATIONS not granted — press Allow / enable in settings`);
  });

  describe('receiver states (sender = iPhone, manual)', function () {
    beforeEach(function () { if (SENDER !== 'manual') this.skip(); });

    it('TC-PUSH-01: app open, not in the chat → push arrives', async () => {
      await d.activateApp(APP_ID);
      await goTab(d, 'חיפוש');
      await (await byText(d, 'חיפוש')).waitForDisplayed({ timeout: 15000 }); // bottom nav visible → not inside a chat
      await expectPushFromPartner('open');
    });

    it('TC-PUSH-02: app in background → push arrives', async () => {
      await d.activateApp(APP_ID);
      await d.pressKeyCode(3); // HOME
      await d.waitUntil(async () => (await d.queryAppState(APP_ID)) === 3, { timeout: 10000, timeoutMsg: 'app did not go to background' });
      await expectPushFromPartner('bg');
    });

    it('TC-PUSH-03: app killed (like swiped from recents, not force-stopped) → push arrives', async () => {
      await d.activateApp(APP_ID);
      await d.pressKeyCode(3);
      await d.waitUntil(async () => (await d.queryAppState(APP_ID)) === 3, { timeout: 10000 });
      killInBackground(APP_ID);
      await d.waitUntil(async () => !processRunning(APP_ID), { timeout: 10000, timeoutMsg: 'app process still running after am kill' });
      await expectPushFromPartner('killed');
    });

    it('TC-PUSH-04: screen locked → push arrives', async () => {
      await d.activateApp(APP_ID);
      await d.pressKeyCode(3);
      await d.lock();
      try {
        assert.equal(await d.isLocked(), true, 'screen locked');
        await expectPushFromPartner('locked');
      } finally { await d.unlock(); }
    });
  });
});
